let showMenu=()=>{var e=document.querySelector(".js-header-nav-burger");let t=document.querySelector(".js-mobile-menu");var n=document.querySelector(".js-mobile-menu-close");let r=document.body;e&&t&&n&&(e.addEventListener("click",()=>{t.style.transform="translateX(0)",t.style.visibility="visible",r.classList.add("fixed")}),n.addEventListener("click",()=>{t.style.transform="translateX(100%)",t.style.visibility="hidden",r.classList.remove("fixed")}))},initScrollBtn=()=>{var e=document.querySelector(".js-hero-scroll-btn");e&&e.addEventListener("click",e=>{e.preventDefault();e=document.querySelector("#intro");e&&e.scrollIntoView({behavior:"smooth"})})};window.addEventListener("DOMContentLoaded",()=>{showMenu(),initScrollBtn()});